import { field, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${select({ id: "csProperty", label: "Sizing property", options: [{label:"width",value:"width"},{label:"height",value:"height"},{label:"inline-size",value:"inline-size"},{label:"block-size",value:"block-size"},{label:"min-width",value:"min-width"},{label:"max-width",value:"max-width"}], value: "width" })}${select({ id: "csContext", label: "Layout context", options: [{label:"Flex item (default)",value:"flex"},{label:"Grid item",value:"grid"},{label:"Absolutely positioned",value:"abspos"},{label:"Block layout (margin-box)",value:"block"}], value: "flex" })}</div><div class="field-grid">${field({ id: "csFallback", label: "Fallback value", value: "100%", help: "e.g. 100%, auto, -webkit-fill-available" })}${field({ id: "csSelector", label: "Selector", value: ".stretch-card" })}</div><div class="field-grid">${checkbox({ id: "csIncludeFallback", label: "Include -webkit-fill-available fallback", checked: true })}${checkbox({ id: "csMarginBox", label: "Show margin-box explanation", checked: false })}</div>`,generate(root) {const property = root.querySelector("#csProperty").value;const context = root.querySelector("#csContext").value;const fallback = root.querySelector("#csFallback").value.trim() || "100%";const selector = root.querySelector("#csSelector").value.trim() || ".stretch-card";const includeFallback = root.querySelector("#csIncludeFallback").checked;const showMarginBox = root.querySelector("#csMarginBox").checked;const lines = [];lines.push("/* CSS stretch keyword — Chrome 138+ */");lines.push("/* Makes an element fill all available space in its containing block. */");lines.push("/* Equivalent to -webkit-fill-available but standardized. */");lines.push("");lines.push(`${selector} {`);if (includeFallback) {lines.push(` ${property}: -webkit-fill-available; /* Safari/legacy fallback */`);lines.push(` ${property}: ${fallback}; /* generic fallback */`);} else {lines.push(` ${property}: ${fallback}; /* fallback */`);}lines.push(` ${property}: stretch;`);lines.push(`}`);if (showMarginBox) {lines.push("");lines.push("/* stretch resolves to the available space in the containing block. */");lines.push("/* In block layout, stretch uses margin-box sizing — margins are not subtracted. */");lines.push("/* In flex/grid, stretch fills the cross-axis of the container. */");lines.push("/* For abspos items, stretch fills when inset is set: position:absolute; left:0; right:0; */");}lines.push("");lines.push("/* Browser support: Chrome 138+, Edge 138+, Safari 17+, Firefox 121+ */");lines.push("/* stretch replaces -webkit-fill-available and -moz-available with a standardized keyword. */");switch (context) {case "flex":lines.push("/* In flex layout: item stretches to fill the cross-axis (height in row, width in column). */");break;case "grid":lines.push("/* In grid layout: item stretches to fill its grid cell on the specified axis. */");break;case "abspos":lines.push("/* In abspos layout: use with inset to fill available space. */");lines.push("/* position: absolute; inset: 0; width: stretch; */");break;case "block":lines.push("/* In block layout: element stretches to fill the containing block width. */");lines.push("/* Similar to width: 100% but uses margin-box, not content-box. */");break;}const isWidth = property.includes("width") || property.includes("inline");const previewContextStyle = context === "flex"? "display:flex;align-items:flex-start;gap:8px": context === "grid"? "display:grid;grid-template-columns:1fr 1fr;gap:8px": "";const containerStyle = `${previewContextStyle};background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:12px;min-height:${isWidth ? '80px' : '160px'}`;const stretchBox = `<div style="${property}:stretch;${property}:-webkit-fill-available;${property}:-moz-available;background:linear-gradient(135deg,#3b82f6,#8b5cf6);border-radius:6px;padding:14px;color:#fff;font-size:13px;font-weight:600;text-align:center;box-sizing:border-box">stretch</div>`;const preview = `<div><div style="font-size:12px;font-weight:600;margin-bottom:8px;color:#374151">${property}: stretch — ${context} context</div><div style="${containerStyle}">${context === "flex" || context === "grid" ? `<div style="background:#f3f4f6;border-radius:6px;padding:14px;font-size:12px;color:#6b7280;text-align:center;width:80px;flex:none">Fixed<br>item</div>${stretchBox}` : stretchBox}</div><div style="margin-top:8px;font-size:11px;color:#6b7280">${context === "flex" ? "Flex item: stretch fills the cross-axis. The blue box stretches to match the flex container's cross-axis size." :context === "grid" ? "Grid item: stretch fills the grid cell on the specified axis." :context === "abspos" ? "Absolutely positioned: stretch fills when combined with inset values (left:0; right:0)." :"Block layout: stretch fills the containing block width using margin-box sizing."}</div></div>`;return { output: lines.join("\n"), preview };}};